package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Original decimal dividends divided by whole numbers, including exact nonterminating quotients. */
public final class DecimalWholeQuotients {
 private DecimalWholeQuotients(){}
 public static final String ID="decimalDivInt";
 public static boolean supports(String id){return ID.equals(id);}
 public record Givens(String raw,int divisor){}
 public record Originals(String raw,String divisorRaw,BigDecimal dividend,BigInteger divisor){
  public Rational value(){return new Rational(dividend.unscaledValue(),BigInteger.TEN.pow(dividend.scale()).multiply(divisor));}
  public boolean finitePossible(){BigInteger den=value().d;for(int prime:List.of(2,5)){BigInteger p=BigInteger.valueOf(prime);while(den.mod(p).signum()==0)den=den.divide(p);}return den.equals(BigInteger.ONE);}
 }
 public static Originals readGeneral(Question q){if(q==null||!supports(q.skillId)||q.prompt==null||q.prompt.length()>256)return null;Matcher m=Pattern.compile("([0-9]{1,9}(?:\\.[0-9]{1,12})?) [÷/] ([0-9]{1,9})").matcher(q.prompt);if(!m.matches())return null;BigInteger divisor=new BigInteger(m.group(2));return divisor.signum()>0?new Originals(m.group(1),m.group(2),new BigDecimal(m.group(1)),divisor):null;}
 public static Rational value(Question q){Originals v=readGeneral(q);return v==null?null:v.value();}
 public static Question workQuestion(Question q){Originals v=readGeneral(q);if(v==null)return null;Question visible=new Question(q.skillId,q.prompt,v.raw+" / "+v.divisorRaw,v.value().toString());visible.kind="number";visible.stepSupport=q.stepSupport;visible.calculationMethod=q.calculationMethod;visible.answerFormat=q.answerFormat;visible.decimal=q.decimal;return visible;}
 public static Rational numericInput(String value){if(value==null||value.length()>120)return null;String raw=Expression.normalize(value.trim());if(!raw.matches("[+-]?[0-9]+(?:\\.[0-9]+)?(?:/[+-]?[0-9]+)?"))return null;try{String[] parts=raw.split("/",-1);BigDecimal n=new BigDecimal(parts[0]);BigInteger denominator=BigInteger.TEN.pow(n.scale());if(parts.length==2)denominator=denominator.multiply(new BigInteger(parts[1]));return new Rational(n.unscaledValue(),denominator);}catch(RuntimeException invalid){return null;}}
 public static boolean acceptsStep(String value,String expected,String format){if(value==null||value.length()>120)return false;String raw=Expression.normalize(value.trim());if("decimal".equals(format)&&(!raw.contains(".")||raw.contains("/"))||"decimalValue".equals(format)&&raw.contains("/"))return false;Rational actual=numericInput(value),target=numericInput(expected);return actual!=null&&actual.equals(target);}
 public static StudyGuide guide(Question q){Originals v=readGeneral(q);if(v==null)return null;if(v.finitePossible()){Question visible=new Question(ID,q.prompt,"","");DecimalArithmeticRelations.attach(visible);return visible.studyGuide;}int p=v.dividend.scale();BigInteger u=BigInteger.TEN.pow(p),a=v.dividend.unscaledValue(),den=u.multiply(v.divisor),gcd=a.gcd(den);StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-whole-quotient-v1";h.step("나누어지는 수를 쓰세요.","나누어지는 수 x = ","",v.raw);h.frames.get(0).inputFormat="decimalValue";h.step("나누는 수를 쓰세요.","나누는 수 d = ","",v.divisor.toString());h.step("왼쪽 수의 소수점 아래 자릿수를 쓰세요.","옮길 자릿수 p = ","",Integer.toString(p));h.step("옮길 자릿수에 맞는 자릿값 배수를 쓰세요.","자릿값 배수 u = ","",u.toString());h.step("소수점을 옮겨 나누어지는 수를 정수로 쓰세요.","옮긴 수 A = x × u = ","",a.toString());h.step("자릿값 배수에 나누는 수를 곱해 분모를 구하세요.","분모 D = u × d = ","",den.toString());h.step("분자와 분모의 최대공약수를 구하세요.","최대공약수 g = gcd(A, D) = ","",gcd.toString());h.step("옮긴 수를 최대공약수로 나누어 분자를 구하세요.","분자 n = A ÷ g = ","",a.divide(gcd).toString());h.step("분모를 같은 최대공약수로 나누세요.","분모 b = D ÷ g = ","",den.divide(gcd).toString());return h.fractionResult(7,8);}
 public static Map<String,String> references(Question q,int stage,List<String> entries){StudyGuide h=guide(q);if(h==null||entries==null||stage<0||stage>=h.frames.size())return Map.of();List<Integer> needed=List.of();if(h.frames.size()==7){if(stage==2)needed=List.of(0);else if(stage==3)needed=List.of(2);else if(stage==4)needed=List.of(0,2,3);else if(stage==5)needed=List.of(4,1);else if(stage==6)needed=List.of(5,3);}else{if(stage==2)needed=List.of(0);else if(stage==3)needed=List.of(2);else if(stage==4)needed=List.of(0,3);else if(stage==5)needed=List.of(3,1);else if(stage==6)needed=List.of(4,5);else if(stage==7)needed=List.of(4,6);else if(stage==8)needed=List.of(5,6);}Map<String,String> out=new LinkedHashMap<>();for(int index:needed)if(index<stage&&index<entries.size()){StudyGuide.Frame frame=h.frames.get(index);if(acceptsStep(entries.get(index),frame.expected,frame.inputFormat))out.put(frame.before,entries.get(index));}return out;}
 static boolean selectedNaSeven(String id,CurriculumLimits limits){return supports(id)&&limits.wholeDecimalQuotients();}
 static boolean selected(String id,CurriculumLimits limits){return ID.equals(id)&&limits.variedFacts();}
 public static Givens read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(\\d{1,2}\\.\\d{1,3}) [÷/] (\\d{1,2})").matcher(q.prompt);if(!m.matches())return null;int d=Integer.parseInt(m.group(2));return d>0?new Givens(m.group(1),d):null;}
 private static Rational result(Givens v){return Expression.number(v.raw).div(Rational.of(v.divisor));}
 private static boolean terminates(Givens v){try{new BigDecimal(v.raw).divide(BigDecimal.valueOf(v.divisor));return true;}catch(ArithmeticException e){return false;}}
 static Question make(String raw,int divisor){Question q=new Question(ID,raw+" ÷ "+divisor,"","0");Givens v=read(q);if(v==null)throw new IllegalArgumentException("Selected decimal/whole quotient scope");boolean finite=terminates(v);q.answers[0]=finite?new BigDecimal(raw).divide(BigDecimal.valueOf(divisor)).stripTrailingZeros().toPlainString():result(v).toString();q.answerFormat=finite?"decimalValue":"fraction";q.decimal=true;q.stepSupport=false;attach(q);return q.withInputs(Expression.number(raw),Rational.of(divisor));}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.wholeMaximum(99),precision=limits.decimalPlaces(3);if(max<0||max>99||precision<1||precision>3)throw new IllegalArgumentException("Selected decimal/whole quotient supply");int p=1+random.nextInt(precision),count=(max+1)*(int)Math.pow(10,p)*99;return IndexedQuestionSupply.choose(count,i->make(BigDecimal.valueOf(i/99,p).toPlainString(),i%99+1),random,limits,recent);}
 static Question nextNaSeven(Random random,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.wholeMaximum(99),precision=limits.decimalPlaces(3),divisor=limits.wholeDivisorMaximum();if(max<0||max>99||precision<1||precision>3)throw new IllegalArgumentException("Selected decimal/whole quotient supply");int p=1+random.nextInt(precision),count=(max+1)*(int)Math.pow(10,p)*divisor;return IndexedQuestionSupply.choose(count,i->make(BigDecimal.valueOf(i/divisor,p).toPlainString(),i%divisor+1),random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){Originals v=readGeneral(q);if(v==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 필요");String raw=answers.get(0);if(raw.length()>240)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");String input=Expression.normalize(raw.trim());if(input.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");if("fraction".equals(q.answerFormat)&&!input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"분수로 입력 필요");if("decimal".equals(q.answerFormat)&&(!input.contains(".")||input.contains("/"))||"decimalValue".equals(q.answerFormat)&&input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");Rational actual=numericInput(input);if(actual==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");boolean same=actual.equals(v.value());return new Checker.Result(same?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,same?-1:0,same?"계산 확인 완료":"이 계산 확인");}
 public static void attach(Question q){StudyGuide h=guide(q);if(h!=null)q.studyGuide=h;}
}
